const envelope = $input.first().json ?? {};
const headers = envelope.headers ?? {};
const expectedSecret = String($env.EVOLUTION_WEBHOOK_SECRET || '');
const suppliedHeader = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '');
let pathIsValid = false;
try {
  const pathname = new URL(String(envelope.webhookUrl || '')).pathname;
  pathIsValid = pathname.endsWith('/evolution-whatsapp-' + expectedSecret);
} catch {}
if (!expectedSecret || (suppliedHeader !== expectedSecret && !pathIsValid)) {
  return [{ json: { route: 'unauthorized', accepted: false } }];
}
const payload = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;
const instanceName = String(payload.instance || payload.instanceName || '');
const expectedInstance = String($env.EVOLUTION_INSTANCE || 'estudos-whatsapp');
if (instanceName !== expectedInstance) {
  return [{ json: { route: 'ignored', accepted: false, reason: 'instance_mismatch' } }];
}
const event = String(payload.event || '').trim().toUpperCase().replace(/[.-]/g, '_');
const dataList = Array.isArray(payload.data) ? payload.data : [payload.data ?? {}];
const output = [];
for (const entry of dataList) {
  const key = entry?.key ?? entry?.message?.key ?? {};
  const message = entry?.message ?? entry ?? {};
  const remoteCandidates = [key.remoteJidAlt, key.remoteJid, entry?.sender, payload.sender].map((v) => String(v || ''));
  const remoteJid = remoteCandidates.find((v) => /@s\.whatsapp\.net$/.test(v)) || remoteCandidates.find(Boolean) || '';
  const externalId = String(key.id || entry?.messageId || entry?.id || '');
  if (event === 'MESSAGES_UPSERT' || event === 'MESSAGE_UPSERT') {
    const text = String(message.conversation || message.extendedTextMessage?.text || message.imageMessage?.caption || message.videoMessage?.caption || message.buttonsResponseMessage?.selectedDisplayText || message.listResponseMessage?.singleSelectReply?.selectedRowId || '').trim();
    output.push({ json: { route: 'message', companyId: Number($env.WHATSAPP_COMPANY_ID || 10), instanceName, messageId: externalId, phone: remoteJid.split('@')[0].replace(/\D/g, ''), text, fromMe: Boolean(key.fromMe), isGroup: remoteJid.endsWith('@g.us') } });
    continue;
  }
  if (event === 'MESSAGES_UPDATE' || event === 'MESSAGE_UPDATE' || event === 'SEND_MESSAGE') {
    const rawStatus = entry?.update?.status ?? entry?.status ?? message?.status;
    const normalized = String(rawStatus ?? '').toUpperCase();
    const numeric = Number(rawStatus);
    let deliveryStatus = '';
    if (normalized === 'READ' || normalized === 'PLAYED' || numeric === 4 || numeric === 5) deliveryStatus = 'lida';
    else if (normalized === 'DELIVERY_ACK' || normalized === 'DELIVERED' || numeric === 3) deliveryStatus = 'entregue';
    else if (normalized === 'SERVER_ACK' || normalized === 'SENT' || numeric === 2) deliveryStatus = 'enviada';
    else if (normalized === 'ERROR' || normalized === 'FAILED' || numeric === 0) deliveryStatus = 'erro';
    if (externalId && deliveryStatus) output.push({ json: { route: 'receipt', companyId: Number($env.WHATSAPP_COMPANY_ID || 10), instanceName, externalId, deliveryStatus } });
  }
}
return output.length ? output : [{ json: { route: 'ignored', accepted: true } }];

const received = $input.all().map((item) => item.json);
const rows = received.flatMap((value) => Array.isArray(value) ? value : (Array.isArray(value?.body) ? value.body : [value]));
const row = rows.find((item) => item && item.id);
if (!row) return [];
return [{ json: { queueId: row.id, status: $('Validar e normalizar').item.json.deliveryStatus } }];
